/*
 * NTC Thermistor DC Motor Control
 * Temperature-controlled fan/motor speed.
 * Motor is OFF below 30°C, then ramps up to full speed at 70°C.
 */

int thermistorPin = A0;
int motorPin = 9;

float tempLow = 30.0;
float tempHigh = 70.0;

void setup() {
  pinMode(motorPin, OUTPUT);
  Serial.begin(115200);
  Serial.println("NTC thermistor motor control started");
}

void loop() {
  int sensorVal = analogRead(thermistorPin);

  // Convert analog reading to temperature in Celsius
  // Simulator maps -10°C..80°C to 0..1023
  float temperature = (sensorVal * 90.0 / 1023.0) - 10.0;

  // Map temperature to motor speed (0-255)
  int motorSpeed = 0;
  if (temperature >= tempHigh) {
    motorSpeed = 255;
  } else if (temperature > tempLow) {
    motorSpeed = map((int)(temperature * 10), (int)(tempLow * 10), (int)(tempHigh * 10), 0, 255);
    motorSpeed = constrain(motorSpeed, 0, 255);
  }

  analogWrite(motorPin, motorSpeed);

  Serial.print("Temp: ");
  Serial.print(temperature, 1);
  Serial.print(" C  |  Motor: ");
  Serial.print(motorSpeed);
  Serial.println(motorSpeed == 0 ? " (OFF)" : "");

  delay(200);
}
